  str_homeland_dairy_title_1096 = "ลมหายใจของน้ำ",
  str_homeland_dairy_title_1097 = "เทวดาผู้หยั่งรู้",
  str_homeland_dairy_title_1098 = "ฤดูหนาวผ่านไป ฤดูใบไม้ผลิมาถึง",
  str_homeland_dairy_title_1099 = "ภูมิปัญญาของ Caelestite",
  str_homeland_dairy_content_101 = "อืมม นี่คือการเขียนไดอารี่ครั้งแรกที่สวนลอยฟ้า\nฉันอยากสร้างที่นี่ให้เป็นบ้านหลังใหม่ เหมือนกับที่อีราเวลเคยเป็น ก็ไม่แน่ใจเหมือนกันว่าจะทำสำเร็จไหม\nถ้าทุกคนสนับสนุน ฉันก็น่าจะทำได้นะ!",
  str_homeland_dairy_content_102 = "สวนลอยฟ้าเริ่มรู้สึกเหมือนเป็นบ้านแล้วในตอนนี้! ทุกคนมีพลังงานเต็มพิกัด!\nในขณะที่เรายังมีแรงผลักดัน มาสร้างบ้านใหม่ให้ทุกคนต่อไปกันเถอะ! ลงมือกันเลยพวกเรา!",
  str_homeland_dairy_content_1001 = "ดูเหมือนคาร์ลีนจะชอบคิดอะไรเพลิน ๆ อยู่คนเดียวข้างน้ำพุแห่งความหวัง\nให้เธอได้อยู่กับตัวเองไปก็แล้วกันนะ",
  str_homeland_dairy_content_1002 = "ฮิอิโระอธิษฐานอย่างตั้งใจ...\nเธอไม่ได้ภาวนาต่อเทพเจ้าหรือสิ่งใด เธอเพียงหวังว่าการอธิษฐานจะทำให้หนทางในชีวิตของเธอแจ่มชัดขึ้น",
  str_homeland_dairy_content_1003 = "นั่นคารอนกำลังท่องบทกวีใกล้กับจัตุรัสไฮยาซินท์เหรอ...? หรือว่ากำลังร้องเพลงอยู่นะ?\nเอ่อ แต่ว่า ดูเหมือนเขาจะยังไม่ล้มเลิกความฝันด้านศิลปะ และเขาเองก็ เอ่อ... เป็นนักฝันที่น่าชื่นชมจริง ๆ!",
  str_homeland_dairy_content_1004 = "อีฟตั้งใจตระเตรียมสิ่งต่าง ๆ มากมายให้แก่ดอว์นและซินซา แต่ไม่ได้คิดว่าจะหาอะไรให้ตัวเองเลย\nอีฟพึงพอใจ ตราบใดที่เธอได้ใช้เวลากับครอบครัวและทำให้พวกเขามีความสุข ดังนั้นเธอจึงไม่จำเป็นต้องเตรียมอะไรเพิ่มเติมเพื่อตัวเอง",
  str_homeland_dairy_content_1005 = "สโมกกี้เสนอแนะเกี่ยวกับระบบสั่งซื้อสินค้าของอีราเวล โดยได้ไอเดียมาจากความต้องการของเธอเอง เธอเชื่อว่าด้วยระบบนี้ออโรเรียนจะได้ใช้ชีวิตอย่างสะดวกสบายมากขึ้น",
  str_homeland_dairy_content_1006 = "ทาคิสอบถามเคล็ดลับการเล่นว่าวอย่างอ่อนน้อม...\nกลับกลายเป็นว่าเขาอยากเรียนรู้วิธีเล่นว่าวก็เพราะคิดว่าการเล่นว่าวน่าจะเป็นธุรกิจใหม่ที่ทำกำไรได้ดี\nสมแล้วที่เป็นเจ้าของร้านรับสารพัดงานจิปาถะจริง ๆ",
  str_homeland_dairy_content_1007 = "ช่วงนี้ไวซ์งานรัดตัวสุด ๆ\nดูเหมือนการจัดการรายรับและรายจ่ายของที่นี่เป็นเรื่องยากเหลือเกิน...",
  str_homeland_dairy_content_1008 = "ดูเหมือนในที่สุดมิสบลังค์จะได้พักผ่อนสักพัก...",
  str_homeland_dairy_content_1009 = "เชอวานผู้หมกมุ่นในเทคโนโลยีจู่ ๆ ก็นึกขึ้นมาว่าวิทยาการโบราณและวิทยาการของเคเลสไทต์มีสิ่งคล้ายคลึงกันมากมาย...\nความคิดแปลกใหม่นี้เกิดขึ้นเพราะเธอทำงานเกินเวลารึเปล่านะ?",
  str_homeland_dairy_content_1010 = "อาเมะโมริอยากรู้ว่าใครออกแบบสิ่งยอดเยี่ยมนี้ขึ้นมา... เธออยากจะนำเทคนิคนี้ไปใช้ที่เกาะเมฆาบ้าง เพื่อให้ผู้คนมีชีวิตที่ดีขึ้น",
  str_homeland_dairy_content_1011 = "เหยาอธิบายแผนเกษียณของเธออย่างละเอียด และใช้ทรัพย์สินมหาศาลที่มีเพื่อแก้ปัญหาวุ่นวายที่คนทั่วไปเจอ...",
  str_homeland_dairy_content_1012 = "ทัวร์ด็อกยังไม่ล้มเลิกความคิดที่จะจ้างฉันให้วาดภาพ\nแต่ท้ายที่สุด ฉันก็พลิกผันสถานการณ์ได้สำเร็จและขอภาพร่างจากเขา\nอืม... ก็เป็นอะไรที่น่าสนใจเหมือนกันนะ",
  str_homeland_dairy_content_1013 = "ด้วยเหตุผลบางอย่าง ทุกครั้งที่คุยกับแอเชอร์ ฉันก็ไม่รู้ว่าจะโต้ตอบเธอยังไง\nวันนี้เธอบอกว่าที่นี่เหมือนซาลอนเสริมสวย ฉันควรคิดว่านั่นเป็นคำชมรึเปล่านะ?",
  str_homeland_dairy_content_1014 = "วันนี้ ในที่สุดเลนอร์ก็เข้าใจความแตกต่างระหว่างคำสั่งกับคำแนะนำ\nในอนาคต ฉันหวังว่าเธอจะได้เรียนรู้ความงดงามของโลกใบนี้...",
  str_homeland_dairy_content_1015 = "เลดี้วิกตอเรียเชื่อมโยงวัฏจักรของน้ำกับชีวิตของออโรเรียน และคิดสิ่งที่ลึกซึ้งออกมา...",
  str_homeland_dairy_content_1016 = "เฟาสต์มาปรับทุกข์กับฉันอย่างน่าแปลกใจ...\nกระเป๋าเดินทางสีขาวชอบ \"กิน\" อะไรกันแน่? แปลกจังแฮะ",
  str_homeland_dairy_content_1017 = "ไจลส์บอกว่าที่นี่ทำให้ความคิดสร้างสรรค์ของเขาโลดแล่นไม่หยุดยั้ง และเขาก็ร้องเพลงกล่อมเด็กบทใหม่ออกมาด้วย\nแต่ว่า เพลงใหม่บทนี้มีความหมายว่าอะไรกันนะ...?",
  str_homeland_dairy_content_1018 = "ไรน์ฮาร์ตชื่นชมโครงสร้างพื้นฐานที่พอใช้ได้ของที่นี่ และเสนอทฤษฎีใหม่บางอย่าง...\nแต่ว่า เราควรพยายามเข้าใจความคิดของเธอหรือเปล่า?",
  str_homeland_dairy_content_1019 = "กรอนรูชวนฉันมาเล่น \"เกมทายปัญหา\" กับเธอ...\nแน่นอน ฉันแพ้อีกแล้ว!",
  str_homeland_dairy_content_1020 = "อูริเอลเชื่อว่าความเจ็บปวดเป็นสิ่งที่เกิดขึ้นไม่มีวันจบสิ้น ดังนั้นความสุขชั่วครั้งชั่วคราวจึงไร้ความหมาย...\nแต่ถ้าไม่มีความสุข เราจะทนกับพลังอันมหาศาลของความเจ็บปวดได้ยังไงล่ะ?",
  str_homeland_dairy_content_1021 = "คุณวิเวียนเป็นเสนาธิการที่ดีจริง ๆ...\nเธอสนใจชิงช้าของที่นี่มาก ๆ และอยากจะสร้างชิงช้าให้ทั่วอิลลูมินา",
  str_homeland_dairy_content_1022 = "เจนมีปัญหากับบางอย่าง\nสำหรับผู้บันทึกเรื่องราวแห่งตรอกมืด เธอจะต้องทำหน้าที่อย่างซื่อตรง\nแต่ความปรารถนาดีของเธอทำให้เธอไม่สามารถทำเช่นนั้นได้ คนอื่น ๆ จะคิดยังไงกับเรื่องนี้นะ?",
  str_homeland_dairy_content_1023 = "กลายเป็นว่า สิ่งที่แม็กกี้ไม่ชอบที่สุดนั้น ไม่ใช่การโดนมองเป็นสิ่งมีชีวิตชนิดอื่น แต่เป็นทัศนคติที่คนอื่นมีต่อเธอต่างหาก",
  str_homeland_dairy_content_1024 = "ตุ๊กตาล้มลุกมีเครื่องยนต์ความร้อนอยู่ภายใน และบร็อคจะต้องซ้อมค่อยมวยกับมันอย่างต่อเนื่อง เพื่อให้สวนลอยฟ้าทั้งสวนทำงานได้ต่อไป?!\nมีคนแกล้งหมอนั่นอีกแล้วสินะ...",
  str_homeland_dairy_content_1025 = "ดูเหมือนทวีตตี้จะชอบสวนลอยฟ้ามาก ๆ\nแต่เธอจะซ่อนหางน้อย ๆ ของเธอจะซ่อนสิ่งต่าง ๆ ได้เยอะแค่ไหน?",
  str_homeland_dairy_content_1026 = "พิตต์แมนกลับมาขี่ม้าโยกเวลาไม่มีใครอยู่ทุกครั้ง\nฉันไม่เข้าใจว่าเพราะอะไร แต่ก็ยังสัญญากับเขาว่าจะช่วยปิดเรื่องนี้เป็นความลับ",
  str_homeland_dairy_content_1027 = "บาร์ตันอยากใช้สวนลอยฟ้าเป็นฐานกลยุทธ์...\nด้วยเหตุนี้ เราจึงพูดคุยหารือกันอย่างลึกซึ้ง",
  str_homeland_dairy_content_1028 = "เหมือนว่าชาโรนากำลังฝึกวิชามังกรลับที่เธออ่านเจอในนิยาย...\nฉันนึกว่าเธอจะช็อคกับความไร้สาระของนิยายนั่นซะอีก แต่พอฟังคำตอบของเธอ ฉันก็ต้องประหลาดใจ",
  str_homeland_dairy_content_1029 = "เอซี่เหมาของที่ขายในร้านหมดเลย\nสงสัยจังว่าเมื่อไหร่ฉันจะใช้เงินอย่างเธอได้บ้าง...",
  str_homeland_dairy_content_1030 = "คอนนอลลีกำลังฝึกไม่ให้ตัวเองประหม่าตามคำแนะนำของไวซ์...\nเพื่อให้ตัวเองเคยชินกับแสงสว่าง คอนนอลลีพยายามเล่นเพลงที่จัตุรัสไฮยาซินท์ และมันก็ได้ผลดีซะด้วย",
  str_homeland_dairy_content_1031 = "ซินซาเชื่อว่าสวนลอยฟ้าไม่มีสถานที่สำหรับต่อสู้และแข่งรถ และเขาก็กังวลว่าอีฟจะไม่ชอบสภาพแวดล้อมในหอพักหญิง...\nถึงจะดูเป็นเรื่องจุกจิกวุ่นวาย แต่ถ้ามองอีกมุมหนึ่ง ซินซาก็เป็นผู้นำและเป็นพี่ชายที่ดี อีกทั้งยังใส่ใจกับรายละเอียด",
  str_homeland_dairy_content_1032 = "เฟลอร์คิดว่าการซ่อมเครื่องจักรของออโรเรียนในสายงานต่าง ๆ จะนำความสนุกครั้งใหม่มาให้... หลังจากคุยกับเขา ฉันพบว่าเขามีความสุขยิ่งกว่านั้นอีก...",
  str_homeland_dairy_content_1033 = "ฉันถามแกรมอย่างละเอียดเกี่ยวกับเคล็ดลับการพัฒนาทักษะการทำอาหาร\nเขาบอกฉันว่าการทำอาหารไม่มีสิ่งที่เรียกว่าพรสวรรค์ การฝึกเท่านั้นที่เป็นหนทางเดียวในการพัฒนา ขณะทำอาหารเราจะต้องมีสมาธิ และปรุงด้วยความรักเพื่อให้รสชาติดีขึ้น",
  str_homeland_dairy_content_1034 = "องค์ราชินีชื่นชมหอคอยไฮยาซินท์ในอีราเวลอย่างยิ่ง และฉันก็โชคดีที่ได้รับการชี้แนะจากเธออีกครั้ง",
  str_homeland_dairy_content_1035 = "ดูเหมือนบาร์ตันจะไม่ใช่แค่คนคลั่งสงคราม แต่ยังคลั่งการต่อสู้สุด ๆ... เขาถึงขั้นพยายามอย่างหนักเพื่อสังเกตท่วงท่าต่าง ๆ ในการดวลของคนสองคน\nแต่... เดี๋ยวนะ ทำไมมีคนสู้กันที่นี่ด้วยล่ะ?!",
  str_homeland_dairy_content_1036 = "เคลเคนโม้กับฉันว่าเขาเรียนรู้ความสามารถใหม่มา... ซึ่งก็เป็นอย่างที่คิด เขาหลอกฉันอีกแล้ว!\nแต่อย่างไรก็ตาม เมื่อได้รู้เรื่องราวเบื้องหลังเทคนิคการมองตา ฉันก็โกรธเขาไม่ลง...",
  str_homeland_dairy_content_1037 = "ปิแอร์บอกว่าพวกเขาสนุกกับชีวิตที่นี่ และฉันก็ดีใจเหมือนกัน เพราะดูเหมือนพวกเด็ก ๆ จะพูดจาล้อเลียนและแกล้งคนอื่นน้อยลง...\nแต่ความสุขนั้นก็จบลงกะทันหัน เมื่อได้รู้ว่าเจ้าไก่คลักกี้ทำอะไรลงไป",
  str_homeland_dairy_content_1038 = "ฉันเดินตามก้อนขนปุยสีเงินบนพื้นไปจนถึงกองฟาง และฟิลิชีซึ่งเป็นเจ้าของขนพวกนั้นก็กำลังนอนกรนเบา ๆ อยู่\nเพื่อไม่ให้คนอื่นเจอปัญหาแพ้ขนแมว ฉันเลยจำเป็นช่วยฟิลิชีแปรงขน...",
  str_homeland_dairy_content_1039 = "ไฮแดรดบอกฉันว่าเมื่อวานซืนเขาต่อสู้แย่งสินค้ากับคนอื่นที่ตลาดมืดอัมบราตันจนบาดเจ็บ\nพอได้รู้ว่าไฮแดรดต้องการอะไร ฉันก็ได้รู้ว่าเขามีมุมที่คาดไม่ถึงอยู่ด้วย...",
  str_homeland_dairy_content_1040 = "เจเนวีฟชอบบรรยากาศของที่นี่ ไม่ใช่เพราะที่นี่มีเหล้าจินที่เธอโปรดปรานเท่านั้น แต่เธอชอบดอกไม้ของที่นี่ด้วย...\nแต่ว่า ฉันก็ได้เห็นปฏิกิริยาที่น่าสนใจจากเธอ เมื่อเธอได้รู้ว่าทุกอย่างเป็นฝีมือของสโมกกี้ที่แอบจัดการสิ่งต่าง ๆ ให้เธออย่างลับ ๆ",
  str_homeland_dairy_content_1041 = "เรจินากำลังเขียนซิงเกิ้ลใหม่อยู่ และเธอก็ขอคำแนะนำจากฉัน...\nแต่จากคำพูดของเธอ ฉันก็ได้รู้อะไรมากขึ้น ที่จริงเธอไม่ได้รังเกียจบาร์บาร่ามากนัก เรจินาเกลียดเพื่อนร่วมงานคนอื่น ๆ ที่ทำตัวเสแสร้งและไม่เป็นตัวเองมากกว่า",
  str_homeland_dairy_content_1042 = "ไม่นึกเลยว่าแพกต์จะชอบชิงช้าขนาดนี้\nเราควรจะสร้างเพิ่มในอนาคตดีไหมนะ?",
  str_homeland_dairy_content_1043 = "วันนี้ ในที่สุดฉันก็ชวนอาเรียออกมาเดินเล่นข้างนอกได้สักที\nหวังว่ารอยยิ้มของเธอจะอยู่กับเธอตลอดไป",
  str_homeland_dairy_content_1044 = "คาฟกาบอกฉันว่าฟรานซ์ดีใจมาก ที่นี่มีที่พื้นที่กว้างขวาง และเขาก็ได้เจอเพื่อนเล่นใหม่มากมาย... แถมยังไม่น้ำลายไหลมากเหมือนแต่ก่อนด้วย!\nเอ่อ เดี๋ยวนะ... แล้วน้ำลายพวกนั้นลดลงเพราะอะไรกันนะ?",
  str_homeland_dairy_content_1045 = "เนลส์เข้าใจผิด คิดว่าผู้คนมาสารภาพบาปต่อหน้าน้ำพุแห่งความหวัง เขาก็เลยเริ่มสารภาพไม่หยุด...\nหวังว่าเขาจะสงบใจได้จริง ๆ นะ",
  str_homeland_dairy_content_1046 = "ดูเหมือนว่ายูริอาห์จะชอบทิวทัศน์ของอีราเวลมาก ๆ\nฉันใช้โอกาสนี้เล่าถึงความปรารถนาที่มีมายาวนาน และโชคดีที่เธอก็ยินดีจะช่วยฉัน",
  str_homeland_dairy_content_1047 = "ใช้ชีวิตหนึ่งวันให้เต็มที่... ไลฟ์สไตล์ของเทสซาค่อนข้างน่าอิจฉา\nแต่ไม่ใช่ทุกคนจะมีอิสระได้ง่าย ๆ หรอกนะ",
  str_homeland_dairy_content_1048 = "ฮาชิอยากเปลี่ยนสวนลอยฟ้าเป็นโถงนิทรรศการทางธรรมชาติ\nอ้างว่าการทำแบบนั้นจะดึงดูดนักท่องเที่ยวและนำมาซึ่งรายได้มากมาย\nฉันควรเชื่อเขาดีไหม? ฟังดูเหมือนกับดักเลย!",
  str_homeland_dairy_content_1049 = "ดูเหมือนไวซ์จะไม่สบายใจนิดหน่อย คงเป็นเพราะเรื่องในตอนนั้น\nโชคดีที่มุกตลกฝืด ๆ ของฉันทำให้เธอหัวเราะออก\nเธอช่วยฉันมามากมายเหลือเกิน ฉันจะต้องช่วยไวซ์ตามหาอดีตของตัวเองให้ได้",
  str_homeland_dairy_content_1058 = "นีน่าขี่ม้าเป็นตั้งแต่เด็ก เธอจึงไม่เคยขี่ม้าโยกเลย\nเมื่อเธอได้ยินว่ามีคนที่ไม่มีเงินซื้อม้าโยก จึงได้ตัดสินใจทำขึ้นมาส่วนหนึ่งเพื่อมอบให้กับคนที่อยากได้\nเพราะว่า... นีน่าเป็นคนใจอ่อนนั่นเอง",
  str_homeland_dairy_content_1059 = "ซานาเอะตัดสินใจตั้งชื่อสวนแห่งนี้ว่าแปลงดอกไม้แห่งรัก\nและยังสัญญาว่าจะดูแลมันอีกด้วย\nอย่างไรก็ตาม สิ่งเดียวที่ฉันต้องการก็คือให้เธอเลิกเดินสะดุดตลอดเวลาสักที... แค่เห็นก็เจ็บแทนแล้ว!",
  str_homeland_dairy_content_1060 = "ดอว์นกำลังใช้ความคิดเงียบ ๆ อยู่ที่โต๊ะทำงาน...\nฉันแปลกใจตอนที่ดอว์นบอกว่าเธอแยกแยะว่าใครเป็นใครได้จากการฟังแค่เสียงฝีเท้า\nเฮ้อ แต่ทุกอย่างย่อมมีข้อยกเว้น... อย่างน้อยเหตุผลที่เธอใช้ระบุตัวซินซานั้นก็ทำให้อึ้งอยู่เหมือนกัน",
  str_homeland_dairy_content_1061 = "ดูเหมือนว่าบาร์บาร่าจะกำลังฝึกซ้อมซิงเกิลใหม่อยู่บนเวทีเพลงซาคิ แต่ท่าทางเธอจะมีความกังวลอยู่บ้าง...\nหลังจากพูดคุยกับเธอแล้ว แม้ทัศนคติของบาร์บาร่าในเรื่องดนตรีใหม่ ๆ จะทำให้ฉันตกใจ แต่ทัศนคติของเธอในเรื่องอื่น ๆ ก็ไม่เกินความคาดหมายของฉัน...",
  str_homeland_dairy_content_1062 = "ลีโอนากำลังฝึกชกมวยอย่างขะมักเขม้น ราวกับเธอนั้นเต็มไปด้วยความขุ่นเคือง...\nกลายเป็นว่านี่คือวิธีระบายของเธอ\nแต่ว่านะ รู้สึกว่าฉันจะพูดอะไรที่ไม่ควรพูดออกไปซะแล้วสิ...",
  str_homeland_dairy_content_1063 = "นาโรเซลกำลังคุยกับหมู่นกอยู่ที่โต๊ะทำงานของเธอ...\nเธอเป็นห่วงเรื่องอารมณ์ความรู้สึกของฉันในช่วงนี้ ก็เลยสอนเทคนิคการหายใจให้",
  str_homeland_dairy_content_1064 = "มิการ์ดเป็นคนที่เก่งกาจสมชื่อในฐานะเจ้าหน้าที่ผู้เชี่ยวชาญด้านเทคโนโลยีชีวภาพ มองปราดเดียวเธอก็รู้แล้วว่าต้นไม้ต้นไหนตัดแต่งพันธุกรรมมา!",
  str_homeland_dairy_content_1065 = "อย่างที่ Nina คาดไว้... เธอไม่เคยปล่อยให้แรงบันดาลใจใดๆ หลุดลอยไป!\nฉันน่าจะเรียนรู้จากความดื้อรั้นของเธอเมื่อต้องไล่ตามความฝันของเธอ",
  str_homeland_dairy_content_1066 = "วันนี้ฉันได้พบกับซาห์น หัวหน้ากลุ่มแพ็งกาโล เขาออกจะเงียบขรึมและสงวนท่าที แม้ว่าการสนทนาของเราจะเป็นไปอย่างขลุกขลัก แต่สุดท้ายก็ลงเอยด้วยดี",
  str_homeland_dairy_content_1067 = "ฉันแปลกใจมากที่พวกแพ็งกาโลปลื้มเพลงเดทเมทัลของเรจินา! พวกเขาถึงกับตั้งกลุ่มแฟนคลับไปเชียร์เธอเลยนะ! ถึงจะดูประหลาด ๆ แต่ทุกคนก็มีความสุขมาก",
  str_homeland_dairy_content_1068 = "คาร์ลีนจ้องมองที่ฝ่ามือของเธอ ทันใดนั้นเธอก็กำฝ่ามือแน่นราวกับว่าเธอได้ตัดสินใจเกี่ยวกับบางสิ่งบางอย่างหรือตั้งปณิธานแล้ว... ปรากฎว่าตอนนี้เธอเข้าใจ \"ความหมายของคำอธิษฐาน\" แล้ว",
  str_homeland_dairy_content_1069 = "เบริลอยู่ที่ริมแม่น้ำตลอดเลยเหรอ? หรือว่า...\nที่ไหนได้ ฉันเข้าใจผิดไปเอง มิหนำซ้ำยังโดนเบริลอำด้วย\nแต่ก็ไม่เป็นไรหรอก ถ้ามันจะทำให้เบริลรู้สึกผ่อนคลาย นั่นก็ดีที่สุดแล้ว",
  str_homeland_dairy_content_1070 = "ช่วงนี้เซียลมีปัญหาเรื่องการคำนวณที่ผิดพลาดในพิมพ์เขียวชุดหนึ่ง เธอถึงกับคิดว่าจะมาทำงานให้ฉันเพื่อหาเงินไปซื้อเครื่องคิดเลขแบบกลไกราคาแพง\nในที่สุดเธอก็รู้ว่าตัวเองเข้าใจผิดไป ไม่ใช่พิมพ์เขียว\nดูเหมือนว่าบางครั้งแรงบันดาลใจก็เป็นส่วนหนึ่งของพิมพ์เขียวเช่นกัน",
  str_homeland_dairy_content_1071 = "ฟีญ่ามีความสุขมากจนปิดบังไว้ไม่มิดจริง ๆ\nพอได้รับอิทธิพลจากเธอ ฉันเลยเล่นสไลเดอร์อยู่พักใหญ่",
  str_homeland_dairy_content_1072 = "ฉันงีบหลับบนเก้าอี้นั่งเล่นตลอดช่วงบ่ายเลย\nจำได้คร่าว ๆ ว่าเจโน่เป็นคนทำให้ฉันหลับไป... นี่ฉันคงไม่ได้ฝันอยู่หรอกนะ ใช่ไหม?",
  str_homeland_dairy_content_1073 = "การ \"ปกป้อง\" สิ่งที่คุณรัก ทำได้มากมายหลายวิธี\nนี่คือสิ่งที่ได้เรียนรู้จากเรนโบว์ในวันนี้",
  str_homeland_dairy_content_1076 = "แม้จะอยู่ใน Cloud Gardens พอลลักซ์ก็ยังคงรักษากิจวัตรและนิสัยของเธอจากความสบาย",
  str_homeland_dairy_content_1077 = "พาโลมามักจะใช้คำพูดที่คมคายเพื่อกลบเกลื่อนว่าเธอคิดถึงครอบครัวมากเพียงใด ฉันหวังว่าเธอจะสามารถเยี่ยมชม Cloud Gardens ได้บ่อยๆ ในอนาคตและพบกับความสงบภายใน",
  str_homeland_dairy_content_1078 = "คาสต้าอาจไปไม่ถึงคาสิโน แต่เธอจับปลาได้มากมายริมแม่น้ำ...\nการจับของเธอทำให้เธอมีความสุขมากกว่าการพนัน\nเดาว่านั่นคือเสน่ห์ของการตกปลา!",
  str_homeland_dairy_content_1079 = "เฮดี้ชอบไอศกรีมด้วย ดังนั้นในที่สุดเราก็พบจุดร่วม!\nแต่ไอศกรีมรส \"หนังสือเก่า\" มีอยู่จริงหรือไม่?",
  str_homeland_dairy_content_1080 = "ผู้พิพากษาจูเนียร์ชอบรูปปั้นสไตล์คาเลสไทต์\nฉันทำดินให้เขาหนึ่งก้อน แต่ดูเหมือนเขาจะไม่ค่อยพอใจเท่าไหร่นัก",
  str_homeland_dairy_content_1081 = "ตามคาดของลิลิก้า! เธอค้นพบจริงๆ ว่าคุณควรจะทำอะไรกับตุ๊กตาวินเดลเลียน\nลิลิกาสัญญากับฉันด้วยว่าเธอจะสร้างภาพยนตร์เกี่ยวกับเอราวีล แต่ฉันหวังว่าเธอจะเขียนบทได้อย่างถูกต้อง...",
  str_homeland_dairy_content_1082 = "ขอบคุณ Minos ที่ทำให้ฉันได้ค้นพบว่าประติมากรรมเทียน Windelion ทำงานอย่างไร!",
  str_homeland_dairy_content_1083 = "ใครจะเดาได้ว่า Sadie มีพรสวรรค์ด้านดนตรีเช่นนี้? ทุกคนที่ฟังท่วงทำนองของกลองก็อดไม่ได้ที่จะโยกไปกับมัน\nคราวหน้าฉันจะร้องเพลงฮิปฮอปให้ทุกคน!",
  str_homeland_dairy_content_1084 = "ถ้ามิเชนนี่ดูแลสัตว์ตัวน้อยและเฝ้าดูพวกมันเติบโต เธออาจจะเข้าใจ...\nว่าความสำคัญของชีวิตเป็นสิ่งที่วัดค่าไม่ได้",
  str_homeland_dairy_content_1085 = "วันนี้ฉันตัดสินใจสร้างสตูดิโอภาพยนตร์ใน Cloud Gardens สำหรับทุกคน",
  str_homeland_dairy_content_1086 = "เบเร็ตต้ามีวินัยในตนเองมากและยืนหยัดที่จะวิ่งทุกวัน ฉันเพิ่งรู้ในวันนี้ว่าเธอกำลังพยายามปรับปรุงสมรรถภาพร่างกายของเธอและเป็นแพทย์ที่ดีขึ้น เธอคู่ควรกับการชื่นชมของฉันจริงๆ",
  str_homeland_dairy_content_1087 = "Axelia ปรากฏตัวใกล้กับ Windelion Drum เมื่อไม่นานมานี้...\nหลังจากคุยกับเธอ ตอนนี้ฉันเข้าใจแล้วว่าทำไมเธอถึงชอบดนตรีอิเล็กทรอนิกส์",
  str_homeland_dairy_content_1088 = "นาดีนอาสาที่จะเป็น Nightwatch of Cloud Gardens ฉันจะเพิกเฉยต่อการช่วยเหลือของเธอไม่ได้แม้ว่าเธอจะอาสาทำหน้าที่นี้ก็ตาม!\nฉันต้องคิดถึงรางวัลสำหรับนาดีน...",
  str_homeland_dairy_content_1089 = "เพื่อที่จะได้เป็นนักตกปลาที่เก่งที่สุดอย่างไร้ข้อโต้แย้งและได้รับเงินทุนสำหรับพิพิธภัณฑ์ ฉันสมัครเข้าร่วมการแข่งขันตกปลาที่จับได้แบบไม่ธรรมดา",
  str_homeland_dairy_content_1090 = "ในที่สุด ด้วยกำลังใจ ฉันเอาชนะนักตกปลาระดับปรมาจารย์ทุกคนและแชมป์เก่า แม้ว่าฉันจะไม่ได้รับเงินทุนที่ต้องการ แต่ฉันก็พิสูจน์แล้วว่าฉันเป็นนักตกปลาที่เก่งที่สุดใน Eraveil",
  str_homeland_dairy_content_1091 = "เป็นเรื่องผิดปกติที่เห็นวิคออกไปนอกห้องของเขา และเป็นไปตามคาด เขากำลังวางแผนเล่นตลกมากขึ้นไปอีก... เขากำลังพยายามเปลี่ยนสถานที่นี้และโคลอสซัสให้เป็นศูนย์วิจัยส่วนตัวของเขาเองงั้นเหรอ!?",
  str_homeland_dairy_content_1092 = "อัลบั้มใหม่ต้องการไดนามิกใหม่และธีมใหม่ แต่สไตล์แบบไหนดีที่สุด? โกลดีไม่แน่ใจว่าเธอควรทำอย่างไร แต่ไม่ว่าเธอจะเลือกสไตล์ไหน เธอก็จะทำมันออกมาได้อย่างสมบูรณ์แบบอย่างแน่นอน!",
  str_homeland_dairy_content_1093 = "บรั่นดียุ่งกับการถ่ายภาพไปทั่วอีกครั้ง ครั้งนี้ เธอถ่ายภาพได้สมบูรณ์แบบโดยไม่ตั้งใจ โดยจับแสงได้อย่างสะเทือนใจที่สุด เดาว่าทำไมเขาถึงบอกว่าการถ่ายภาพคือศิลปะของแสงและเงา...",
  str_homeland_dairy_content_1094 = "แมวเข้ายึดหิ้ง พวกเขาดูเหมือนจะรักมันมาก...",
  str_homeland_dairy_content_1095 = "Liqing กำลังมองหา Tinytail จอมขี้เกียจ แต่ดูเหมือนว่าเขาจะ...",
  str_homeland_dairy_content_1096 = "Yuebai กล่าวว่าหากคุณต้องการเป็นนักว่ายน้ำที่เชี่ยวชาญ คุณต้องรู้สึกถึงลมหายใจของน้ำ และถ้าคุณต้องการรู้สึกถึงลมหายใจของน้ำ คุณต้องยืนอยู่ที่ริมน้ำเป็นเวลา 10,000 ชั่วโมง มันควรจะเป็นจริงหรือไม่?",
  str_homeland_dairy_content_1097 = "ไมเคิลดูเหมือนจะกังวลว่าเชิงเทียนที่นี่จะทำให้เกิดไฟไหม้โดยไม่ได้ตั้งใจ แต่บางทีเธออาจจะแค่หาข้ออ้างที่จะซื้อมัน?",
  str_homeland_dairy_content_1098 = "Cloud Gardens เป็นหนทางที่ห่างไกลจากซากปรักหักพังรกร้างที่ Eraveil เคยเป็น ทิวทัศน์นั้นสร้างความประทับใจให้กับ Jeriah อย่างลึกซึ้ง",
  str_homeland_dairy_content_1099 = "Kya ขี่แก้วกาแฟหมุนเป็นครั้งแรก ซึ่งดูจะเข้มข้นไปหน่อยสำหรับเธอ หลังจากมีอาการวิงเวียนศีรษะ เธอจึงกำหนดสิ่งสำคัญที่สุดของงานใหม่ตามลำดับ...",
  str_homeland_dairy_reply_101 = "แน่นอนว่าเราต้องทำได้ ผู้นำทาง!",
  str_homeland_dairy_reply_102 = "มาส่งเสียงเชียร์ 15 ครั้งกันทุกเช้า เริ่มตั้งแต่พรุ่งนี้เลย!",
