  str_homeland_dairy_condition_1120 = "Cuscuta คาดหวังไว้สูงกว่านี้มาก <color=#FEF49B>ความสามารถในการอยู่อาศัย</color> สำหรับสถานที่แห่งนี้",
  str_homeland_dairy_condition_1121 = "Mia: Lustrous Soul ดูเหมือนจะสนใจเรื่องนั้นมาก <color=#FEF49B>ลูกแก้วรีกัลรีเมมเบรนซ์</color>.",
