  str_homeland_dairy_condition_1123 = "บล็องก์: ดูเหมือนว่า Pura Cordis กำลังมองหาสถานที่ที่ใช่ <color=#FEF49B>ร่มเย็นและอบอวลไปด้วยความเขียวขจี</color>.",
